package com.example.starter.tag.domain;

import java.time.Instant;

/**
 * 野外站点。站点编号为合成编号，不包含真实位置数据。
 */
public class Site {

    private Long id;
    private String siteCode;
    private String name;
    private Instant createdAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getSiteCode() {
        return siteCode;
    }

    public void setSiteCode(String siteCode) {
        this.siteCode = siteCode;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Instant createdAt) {
        this.createdAt = createdAt;
    }
}

package com.example.starter.tag.domain;

import java.time.Instant;

/**
 * 合成动物个体。编号由系统合成生成，不记录真实位置数据。
 */
public class Animal {

    private Long id;
    private String animalCode;
    private String species;
    private Instant createdAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getAnimalCode() {
        return animalCode;
    }

    public void setAnimalCode(String animalCode) {
        this.animalCode = animalCode;
    }

    public String getSpecies() {
        return species;
    }

    public void setSpecies(String species) {
        this.species = species;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Instant createdAt) {
        this.createdAt = createdAt;
    }
}

package com.example.starter.tag.domain;

import java.time.Instant;

/**
 * 标签。当前持有站点 {@link #holderSiteId} 表示标签所有权归属；
 * 标签可在站点之间通过交接转移。
 */
public class Tag {

    private Long id;
    /** 标签业务编号，如 L。 */
    private String tagCode;
    /** 当前持有站点主键；交接确认后更新为接收站点。 */
    private Long holderSiteId;
    private Instant registeredAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getTagCode() {
        return tagCode;
    }

    public void setTagCode(String tagCode) {
        this.tagCode = tagCode;
    }

    public Long getHolderSiteId() {
        return holderSiteId;
    }

    public void setHolderSiteId(Long holderSiteId) {
        this.holderSiteId = holderSiteId;
    }

    public Instant getRegisteredAt() {
        return registeredAt;
    }

    public void setRegisteredAt(Instant registeredAt) {
        this.registeredAt = registeredAt;
    }
}

package com.example.starter.tag.domain;

import java.time.Instant;

/**
 * 标签附着记录（标签与动物的关联区间）。
 *
 * <p>区间采用 UTC 时间、左闭右开：{@code [attachAt, detachAt)}；
 * {@link #detachAt} 为 {@code null} 表示当前仍然有效（标签仍附着在该动物身上）。
 * 摘除时只回填结束时刻冻结上一段关联，不覆盖历史。
 */
public class Attachment {

    private Long id;
    private Long animalId;
    private Long tagId;
    /** 执行附着的站点主键。 */
    private Long siteId;
    /** 附着起始时刻（UTC，含）。 */
    private Instant attachAt;
    /** 摘除时刻（UTC，不含）；null 表示当前有效。 */
    private Instant detachAt;
    /** 完成摘除操作的站点主键；null 表示尚未摘除。 */
    private Long detachSiteId;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getAnimalId() {
        return animalId;
    }

    public void setAnimalId(Long animalId) {
        this.animalId = animalId;
    }

    public Long getTagId() {
        return tagId;
    }

    public void setTagId(Long tagId) {
        this.tagId = tagId;
    }

    public Long getSiteId() {
        return siteId;
    }

    public void setSiteId(Long siteId) {
        this.siteId = siteId;
    }

    public Instant getAttachAt() {
        return attachAt;
    }

    public void setAttachAt(Instant attachAt) {
        this.attachAt = attachAt;
    }

    public Instant getDetachAt() {
        return detachAt;
    }

    public void setDetachAt(Instant detachAt) {
        this.detachAt = detachAt;
    }

    public Long getDetachSiteId() {
        return detachSiteId;
    }

    public void setDetachSiteId(Long detachSiteId) {
        this.detachSiteId = detachSiteId;
    }
}

package com.example.starter.tag.domain;

import java.time.Instant;

/**
 * 站点间标签交接记录。
 *
 * <p>交接由当前持有站点发起（{@link #status}=PENDING），接收站点确认后变为
 * CONFIRMED 并转移标签持有权；确认前可由发起方取消（CANCELLED），
 * 接收方也可拒绝（REJECTED）并记录 {@link #rejectReason}。
 * 所有时刻均为 UTC。
 */
public class Handoff {

    private Long id;
    private String handoffCode;
    private Long tagId;
    private Long fromSiteId;
    private Long toSiteId;
    private HandoffStatus status;
    /** 发起时刻（UTC）。 */
    private Instant initiatedAt;
    /** 确认时刻（UTC）；未确认/取消/拒绝时为 null。 */
    private Instant confirmedAt;
    /** 取消或拒绝时刻（UTC）；PENDING/CONFIRMED 下按语义为 null。 */
    private Instant closedAt;
    /** 拒绝原因；取消或确认时为 null。 */
    private String rejectReason;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getHandoffCode() {
        return handoffCode;
    }

    public void setHandoffCode(String handoffCode) {
        this.handoffCode = handoffCode;
    }

    public Long getTagId() {
        return tagId;
    }

    public void setTagId(Long tagId) {
        this.tagId = tagId;
    }

    public Long getFromSiteId() {
        return fromSiteId;
    }

    public void setFromSiteId(Long fromSiteId) {
        this.fromSiteId = fromSiteId;
    }

    public Long getToSiteId() {
        return toSiteId;
    }

    public void setToSiteId(Long toSiteId) {
        this.toSiteId = toSiteId;
    }

    public HandoffStatus getStatus() {
        return status;
    }

    public void setStatus(HandoffStatus status) {
        this.status = status;
    }

    public Instant getInitiatedAt() {
        return initiatedAt;
    }

    public void setInitiatedAt(Instant initiatedAt) {
        this.initiatedAt = initiatedAt;
    }

    public Instant getConfirmedAt() {
        return confirmedAt;
    }

    public void setConfirmedAt(Instant confirmedAt) {
        this.confirmedAt = confirmedAt;
    }

    public Instant getClosedAt() {
        return closedAt;
    }

    public void setClosedAt(Instant closedAt) {
        this.closedAt = closedAt;
    }

    public String getRejectReason() {
        return rejectReason;
    }

    public void setRejectReason(String rejectReason) {
        this.rejectReason = rejectReason;
    }
}

package com.example.starter.tag.domain;

import java.time.Instant;

/**
 * 幂等请求键。附着与交接携带 requestId；同一 requestId 同参重放返回首次结果，
 * 异参冲突返回 409。任一事务失败不写入该键，即失败不消费请求键。
 */
public class IdempotentRequest {

    private Long id;
    /** 客户端提供的幂等键。 */
    private String requestId;
    /** 请求类型，如 ATTACH / HANDOFF_INITIATE。 */
    private String requestType;
    /** 首次请求参数的规范化摘要。 */
    private String requestHash;
    /** 首次成功请求产生的业务记录主键。 */
    private Long resultId;
    private Instant createdAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getRequestId() {
        return requestId;
    }

    public void setRequestId(String requestId) {
        this.requestId = requestId;
    }

    public String getRequestType() {
        return requestType;
    }

    public void setRequestType(String requestType) {
        this.requestType = requestType;
    }

    public String getRequestHash() {
        return requestHash;
    }

    public void setRequestHash(String requestHash) {
        this.requestHash = requestHash;
    }

    public Long getResultId() {
        return resultId;
    }

    public void setResultId(Long resultId) {
        this.resultId = resultId;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Instant createdAt) {
        this.createdAt = createdAt;
    }
}

