    @PostMapping("/detach")
    @ResponseStatus(HttpStatus.OK)
    public void detach(@Valid @RequestBody DetachRequest request) {
        tagService.detach(request);
    }

    @PostMapping("/handoffs")
    @ResponseStatus(HttpStatus.CREATED)
